const std = @import("std");

const MinHeap = struct {
    data: [10]i32 = undefined,
    size: usize = 0,

    fn insert(self: *MinHeap, val: i32) void {
        var i = self.size;
        self.data[i] = val;
        self.size += 1;
        while (i > 0) {
            const parent = (i - 1) / 2;
            if (self.data[i] >= self.data[parent]) break;
            const temp = self.data[i]; self.data[i] = self.data[parent]; self.data[parent] = temp;
            i = parent;
        }
    }

    fn extractMin(self: *MinHeap) ?i32 {
        if (self.size == 0) return null;
        const min = self.data[0];
        self.size -= 1;
        self.data[0] = self.data[self.size];
        var i: usize = 0;
        while (true) {
            var smallest = i;
            const left = 2 * i + 1;
            const right = 2 * i + 2;
            if (left < self.size and self.data[left] < self.data[smallest]) smallest = left;
            if (right < self.size and self.data[right] < self.data[smallest]) smallest = right;
            if (smallest == i) break;
            const temp = self.data[i]; self.data[i] = self.data[smallest]; self.data[smallest] = temp;
            i = smallest;
        }
        return min;
    }
};

pub fn main() !void {
    var heap = MinHeap{};
    heap.insert(30);
    heap.insert(10);
    heap.insert(20);
    heap.insert(5);

    while (heap.extractMin()) |val| {
        std.debug.print("{} ", .{val});
    }
    std.debug.print("\n", .{});
}

